window.TADABBUR_TAHA = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة طه (٢٠)، سورةٌ مكّيّةٌ محورُها تثبيتُ النبيِّ ﷺ وأنّ القرآنَ تذكرة؛ فيها قصةُ موسى مطوّلةً (النداءُ والآيات، فرعون، السحرة، بنو إسرائيل، السامري)، وقصةُ آدم، وتسليةُ النبيِّ ﷺ. بُدئت بالحمد. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، والنصُّ القرآنيُّ يُؤخذ من المورفولوجيا وقتَ العرض."},"n":20,"name":"طه","total_ayahs":135,"audio":[],"passages":[{"title":"القرآنُ تذكرةٌ لا مشقّة، وعظمةُ الرحمن","range":[1,8],"theme":"أنّ القرآنَ نزل تذكرةً، وتعظيمُ الله المستوي على عرشِه العالمِ بالسرّ","verses":[{"n":1,"reflection":{"text":"«طه» — حرفان من الحروفِ المقطّعةِ التي افتُتِحت بها بعضُ السور، الله أعلمُ بمرادِه بها، وفيها إشارةٌ إلى إعجازِ القرآنِ المؤلَّفِ من جنسِ حروفِ العربِ الذين عجزوا عن معارضته؛ ففي هذا التسليمُ لله في المتشابهِ وردُّ علمِه إليه؛ فسلّم لله فيما استأثر بعلمه، ولا تتكلّف تأويلَ ما لم يُبيَّن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله في المتشابه، وردُّ علمِه إليه."},"action":{"text":"سلّم لله فيما استأثر بعلمه من المتشابهِ كالحروفِ المقطّعة، ولا تتكلّف القولَ فيها بلا علم؛ واستحضر إعجازَ القرآنِ الذي عجز عنه فصحاءُ العرب."}},{"n":2,"reflection":{"text":"«ما أنزلنا عليك القرآن لتشقى» — ما أنزلنا عليك القرآنَ لتتعب وتشقى بما تحمّله من العبادةِ والدعوةِ فوق طاقتك، بل ليكون لك سعادةً ورحمة؛ ففي هذا أنّ الدينَ يُسرٌ لا عُسر، وأنّ القرآنَ رحمةٌ لا مشقّة؛ فتعامل مع دينك على أنه يُسرٌ ورحمة، ولا تحمّل نفسك ما لا تطيق فتنفر.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ما أنزلنا عليك القرآن لتشقى"],"heart_state":{"text":"استشعارُ يُسرِ الدينِ وأنّ القرآنَ رحمة."},"action":{"text":"خذ دينك بيُسرٍ ورفقٍ بنفسك، فما أنزل الله القرآنَ لتشقى بل لتسعد؛ فاعبد الله بما تطيق وتُداوم عليه، ولا تُثقِل نفسك حتى تملَّ وتنقطع."}},{"n":3,"reflection":{"text":"«إلا تذكرة لمن يخشى» — لكن أنزلناه تذكرةً وعظةً ينتفع بها من في قلبه خشيةٌ من الله؛ ففي هذا أنّ المنتفعَ بالقرآنِ أهلُ الخشية، وأنّ الخشيةَ بابُ الانتفاعِ بالتذكير؛ فاطلب خشيةَ الله في قلبك، فبها تنتفع بالقرآنِ وتتّعظ بمواعظه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["تذكرة لمن يخشى"],"heart_state":{"text":"طلبُ الخشيةِ التي بها يُنتفَع بالقرآن."},"action":{"text":"اسأل الله قلبًا خاشعًا، فبالخشيةِ تنتفع بالقرآنِ وتلين لموعظته؛ واقرأه مستحضرًا أنه تذكرةٌ لك، فتأثّر بوعده ووعيده وأقبل على ما يذكّرك به."}},{"n":4,"reflection":{"text":"«تنزيلا ممن خلق الأرض والسماوات العلى» — هذا القرآنُ تنزيلٌ ممّن خلق الأرضَ والسماواتِ العاليةَ الرفيعة، فمصدرُه العظيمُ يوجب تعظيمه وتلقّيه بالقبول؛ ففي هذا أنّ عظمةَ المُنزِّلِ توجب تعظيمَ المُنزَّل، وأنّ خالقَ الكونِ هو منزّلُ القرآن؛ فعظّم القرآنَ لعظمةِ من أنزله، وتلقَّه بالتسليمِ والإجلال.","source":"تفسير السعدي","grade":"ma'thur"},"names":["خلق الأرض والسماوات العلى"],"heart_state":{"text":"تعظيمُ القرآنِ لعظمةِ من أنزله."},"action":{"text":"عظّم القرآنَ في قلبك وتلقَّه بالإجلالِ والقبول، فقد نزل ممّن خلق السماواتِ والأرض؛ فمن استحضر عظمةَ المتكلّمِ عظّم كلامه وخضع له."}},{"n":5,"reflection":{"text":"«الرحمن على العرش استوى» — الرحمنُ استوى على عرشِه استواءً يليق بجلاله (علوًّا وارتفاعًا حقيقيًّا بلا تكييفٍ ولا تشبيه)؛ ففي هذا إثباتُ صفةِ الاستواءِ لله على ما يليق به، مع اقترانها باسمِ الرحمنِ إشعارًا بسعةِ رحمته مع علوّه؛ فأثبت لله ما أثبته لنفسه بلا تكييف، واعبد الرحمنَ العليَّ الذي وسعت رحمتُه كلَّ شيء.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الرحمن","على العرش استوى"],"heart_state":{"text":"إثباتُ علوِّ الله واستوائه على ما يليق بجلاله."},"action":{"text":"أثبت لله من صفاتِ العلوِّ والاستواءِ ما أثبته لنفسه بلا تكييفٍ ولا تشبيهٍ ولا تعطيل، وعظّمه سبحانه؛ واستشعر أنّ العليَّ الأعلى هو الرحمنُ الذي وسعت رحمته خلقه."}},{"n":6,"reflection":{"text":"«له ما في السماوات وما في الأرض وما بينهما وما تحت الثرى» — له وحده ملكًا وخلقًا وتدبيرًا كلُّ ما في السماواتِ وما في الأرضِ وما بينهما وما تحت التراب؛ ففي هذا إحاطةُ ملكِ الله بكلِّ شيء، وأنه لا مالكَ سواه؛ فاعلم أنّ كلَّ شيءٍ ملكٌ لله، فلا تتعلّق إلا به، ولا تخف ولا ترجُ إلا مالكَ الملكِ كلِّه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ شمولِ ملكِ الله لكلِّ شيء."},"action":{"text":"استحضر أنّ كلَّ ما في الوجودِ ملكٌ لله وحده علوًّا وسفلًا، فلا تعلّق قلبك بمملوكٍ مثلك؛ وأخلص رجاءك وخوفك لمالكِ الملكِ الذي بيده كلُّ شيء."}},{"n":7,"reflection":{"text":"«وإن تجهر بالقول فإنه يعلم السر وأخفى» — وإن تجهر بدعائك أو ذكرك فالله غنيٌّ عن الجهر، فإنه يعلم السرَّ وما هو أخفى منه (ما تُحدّث به نفسك وما لم تنطق به بعد)؛ ففي هذا كمالُ علمِ الله بالخفايا، وأنه لا يخفى عليه شيء؛ فراقب الله في سرّك وخواطرك كما تراقبه في علنك، فهو يعلم ما خفي وما هو أخفى.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يعلم السر وأخفى"],"heart_state":{"text":"مراقبةُ الله في السرِّ والخواطرِ كالعلن."},"action":{"text":"راقب الله في سرِّك وحديثِ نفسك كما تراقبه في علانيتك، فهو يعلم ما أسررتَ وما هو أخفى منه؛ فطهّر باطنك من كلِّ ما يكره أن يطّلع عليه من نيّةٍ أو خاطر."}},{"n":8,"reflection":{"text":"«الله لا إله إلا هو له الأسماء الحسنى» — الله الذي لا معبودَ بحقٍّ سواه، له الأسماءُ الحسنى البالغةُ في الحسنِ غايتَه، الدالّةُ على أوصافِ الكمال؛ ففي هذا إفرادُ الله بالألوهيّة، وإثباتُ أسمائه الحسنى؛ فوحّد الله في عبادتك، وادعُه بأسمائه الحسنى، وتعبّد له بمقتضاها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لا إله إلا هو","له الأسماء الحسنى"],"heart_state":{"text":"توحيدُ الله ودعاؤُه بأسمائه الحسنى."},"action":{"text":"أفرِد الله بالعبادةِ فلا إله إلا هو، وادعُه بأسمائه الحسنى مستحضرًا معانيها؛ فسَلِ الرحمنَ رحمته، والغفورَ مغفرته، وتعبّد لله بمقتضى كلِّ اسمٍ من أسمائه."}}]},{"title":"نداءُ موسى في الوادِ المقدّس","range":[9,16],"theme":"مجيءُ موسى للنارِ فيُنادى، والأمرُ بالتوحيدِ وإقامةِ الصلاةِ لذكرِ الله","verses":[{"n":9,"reflection":{"text":"«وهل أتاك حديث موسى» — وهل بلغك يا محمد خبرُ موسى؟ استفتاحٌ لتشويقِ السامعِ وتهيئتِه لتلقّي القصةِ بعبرتها؛ ففي هذا تعظيمُ شأنِ القصةِ الآتية، وتسليةُ النبيِّ ﷺ بأخبارِ من قبله؛ فأنصت لأخبارِ الأنبياءِ بقلبٍ متّعظٍ، فما قُصَّت إلا لتثبيتِ القلبِ والاعتبار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنصاتُ لأخبارِ الأنبياءِ بقلبٍ متّعظ."},"action":{"text":"أنصت لقصصِ الأنبياءِ في القرآنِ بقلبٍ حاضرٍ متّعظ، مستحضرًا أنها سِيقت لتثبيتِ قلبك وعبرتك؛ فتلمّس في كلِّ قصةٍ الدرسَ الذي يعينك على طاعةِ الله."}},{"n":10,"reflection":{"text":"«إذ رأى نارا فقال لأهله امكثوا إني آنست نارا لعلي آتيكم منها بقبس أو أجد على النار هدى» — حين رأى موسى نارًا في ليلةٍ مظلمةٍ باردةٍ وقد ضلّ الطريق، فقال لأهله: امكثوا إني أبصرت نارًا لعلّي آتيكم منها بشعلةٍ تدفئون بها أو أجد عندها من يدلّني على الطريق؛ ففي هذا أنّ الله يسوق عبده إلى أعظمِ خيرٍ من حيث يطلب حاجةً يسيرة، فذهب يطلب قبسًا فنال النبوّة؛ فاطلب حاجتك واثقًا أنّ الله قد يسوقك بها إلى خيرٍ لا تحتسبه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ الله يسوق العبدَ إلى الخيرِ من حيث لا يحتسب."},"action":{"text":"اسعَ في حاجتك متوكّلًا على الله، وثق أنه قد يسوقك بالسببِ اليسيرِ إلى خيرٍ عظيمٍ لم يخطر لك؛ فموسى خرج يطلب جذوةَ نارٍ فآتاه الله النبوّةَ والكلام."}},{"n":11,"reflection":{"text":"«فلما أتاها نودي يا موسى» — فلما وصل إلى النارِ ناداه الله باسمه: يا موسى، تشريفًا وتلطّفًا في الخطاب؛ ففي هذا إكرامُ الله لموسى بندائه باسمه، ولطفُه في مخاطبةِ عبده؛ فاعلم أنّ الله يتلطّف بعباده ويقرّبهم، فأقبل عليه يقبل عليك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استشعارُ لطفِ الله في مناداةِ عبده وتقريبه."},"action":{"text":"أقبل على الله بقلبك وطاعتك يقبل عليك ويقرّبك، فقد نادى موسى باسمه تلطّفًا وتشريفًا؛ فمن أقبل على الله وجده لطيفًا كريمًا يدنيه ويكرمه."}},{"n":12,"reflection":{"text":"«إني أنا ربك فاخلع نعليك إنك بالواد المقدس طوى» — إني أنا ربّك فاخلع نعليك تأدّبًا وتعظيمًا للبقعةِ الطاهرة، إنك بالوادي المطهّرِ المبارَكِ المسمّى طوى؛ ففي هذا تعظيمُ المواطنِ المقدّسةِ والتأدّبُ فيها، وأنّ التوحيدَ أوّلُ ما يُلقى إلى العبد؛ فعظّم شعائرَ الله وأمكنةَ عبادته، وتأدّب في حضرتِه بقلبٍ خاشعٍ وجوارحَ ساكنة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأدّبُ في مواطنِ العبادةِ وتعظيمُ شعائرِ الله."},"action":{"text":"تأدّب في مواطنِ عبادةِ الله وعظّم شعائره، وأحضِر قلبك ووقارك في صلاتك ومسجدك كما أُمِر موسى أن يخلع نعليه في الوادِ المقدّس؛ فالتعظيمُ ثمرةُ الإجلال."}},{"n":13,"reflection":{"text":"«وأنا اخترتك فاستمع لما يوحى» — وأنا اصطفيتك يا موسى للرسالةِ والتكليم، فاستمع لِما أوحيه إليك بقلبٍ حاضرٍ وإصغاءٍ تامّ؛ ففي هذا أنّ الاصطفاءَ يوجب حسنَ الإصغاءِ للوحي، وأنّ تلقّي كلامِ الله يكون بكمالِ الانتباه؛ فأصغِ لكلامِ الله بقلبك كلَّه، فمن أنصت لوحيه بإجلالٍ انتفع به.","source":"تفسير السعدي","grade":"ma'thur"},"names":["اخترتك"],"heart_state":{"text":"حسنُ الإصغاءِ لكلامِ الله بقلبٍ حاضر."},"action":{"text":"أصغِ لكلامِ الله عند تلاوته وسماعه بقلبٍ حاضرٍ منتبهٍ مُجِلّ، كما أُمِر موسى «فاستمع لما يوحى»؛ فحسنُ الاستماعِ أوّلُ طريقِ الانتفاعِ بالوحي."}},{"n":14,"reflection":{"text":"«إنني أنا الله لا إله إلا أنا فاعبدني وأقم الصلاة لذكري» — إنني أنا الله لا معبودَ بحقٍّ سواي فاعبدني وحدي، وأقم الصلاةَ لتذكرني بها؛ ففي هذا أنّ أوّلَ ما أوحاه الله لموسى التوحيدُ، وأنّ الصلاةَ أعظمُ ما يُذكَر به الله؛ فأخلص العبادةَ لله، وأقم الصلاةَ بحضورِ قلبٍ لتكون ذكرًا حقيقيًّا لله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لا إله إلا أنا","أقم الصلاة لذكري"],"heart_state":{"text":"إخلاصُ العبادةِ لله، وإقامةُ الصلاةِ لذكره."},"action":{"text":"أخلص عبادتك لله وحده، وأقم الصلاةَ في أوقاتها بخشوعٍ وحضورِ قلب لتكون ذكرًا حقيقيًّا له؛ فالصلاةُ عمودُ الذكرِ وصلةُ العبدِ بربّه، فحافظ عليها."}},{"n":15,"reflection":{"text":"«إن الساعة آتية أكاد أخفيها لتجزى كل نفس بما تسعى» — إنّ القيامةَ آتيةٌ لا شكّ فيها، أكاد أُخفي وقتها عن الخلقِ (فلا يعلمه أحد)، لتُجزى كلُّ نفسٍ بما عملت من خيرٍ أو شرّ؛ ففي هذا حتميةُ الساعةِ وخفاءُ وقتها ليجدَّ الناسُ في العمل، وأنّ الجزاءَ على قدرِ السعي؛ فأيقن بالساعةِ واعمل لها، ولا تركن إلى خفاءِ وقتها فتغفل، بل اجعل كلَّ يومٍ كأنه آخرُ عملك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إن الساعة آتية"],"heart_state":{"text":"اليقينُ بالساعةِ والجدُّ في العملِ لها."},"action":{"text":"أيقن بأنّ الساعةَ آتيةٌ وأنّ وقتها مخفيٌّ ليختبر الله جدَّك، فاعمل الصالحاتِ في كلِّ وقتٍ كأنها آتيةٌ غدًا؛ فكلُّ نفسٍ تُجزى بما تسعى، فاجعل سعيك فيما يرضي الله."}},{"n":16,"reflection":{"text":"«فلا يصدنك عنها من لا يؤمن بها واتبع هواه فتردى» — فلا يصرفنّك عن الإيمانِ بالساعةِ والاستعدادِ لها من لا يؤمن بها وانقاد لهواه، فتهلك بمتابعته؛ ففي هذا التحذيرُ من قرناءِ السوءِ وأهلِ الهوى الذين يصدّون عن الحقّ، وأنّ متابعتهم هلاك؛ فاحذر أن يصدّك عن دينك مبطلٌ أو صاحبُ هوى، والزم الحقَّ ولو خالفك الناس.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من صدِّ أهلِ الهوى عن الحقّ."},"action":{"text":"لا تدع منكِرًا للحقِّ أو متّبعًا لهواه يصرفك عن دينك وعملك للآخرة، فمتابعتُهم رداءٌ وهلاك؛ فالزم الحقَّ الذي علمته ولو خالفك أكثرُ الناسِ وسخروا منك."}}]},{"title":"آيتا العصا واليد، والإرسالُ إلى فرعون","range":[17,24],"theme":"تأييدُ موسى بالمعجزتين، وأمرُه بالذهابِ إلى فرعونَ الطاغي","verses":[{"n":17,"reflection":{"text":"«وما تلك بيمينك يا موسى» — وما تلك التي في يدك اليمنى يا موسى؟ سؤالُ تقريرٍ وتنبيهٍ ليتهيّأ موسى لما سيراه من الآية؛ ففي هذا لطفُ الله في تهيئةِ عبده للأمرِ العظيمِ بالتدرّج، وأنّ الحوارَ يفتح القلبَ للعجب؛ فتأمّل لطفَ الله في تدريجِ عباده لما يريد، واستعدَّ لآياتِ الله بقلبٍ متهيّئ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ لطفِ الله في تهيئةِ عبده للأمرِ العظيم."},"action":{"text":"تأمّل كيف يهيّئ الله عبده لما يريد أن يريه بالتدرّجِ واللطف، فلا يفجؤه بالأمرِ العظيم؛ فاستعدَّ لآياتِ الله ومقاديره بقلبٍ متهيّئٍ راضٍ بحكمته."}},{"n":18,"reflection":{"text":"«قال هي عصاي أتوكأ عليها وأهش بها على غنمي ولي فيها مآرب أخرى» — قال موسى: هي عصاي أعتمد عليها في المشي، وأضرب بها الشجرَ ليتساقط ورقُه لغنمي، ولي فيها منافعُ أخرى؛ ففي هذا أنّ موسى أطال الجوابَ أنسًا بمناجاةِ ربّه، وأنّ الأشياءَ اليسيرةَ يجعلها الله آياتٍ عظامًا؛ فاعلم أنّ الله يجعل من أضعفِ الأسبابِ أعظمَ الآيات، فلا تحتقر ما بيدك إذا أراد الله به أمرًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأنسُ بمناجاةِ الله، والعلمُ بأنه يعظّم اليسير."},"action":{"text":"أنِس بمناجاةِ ربّك وأطل الوقوفَ بين يديه في صلاتك ودعائك، واعلم أنّ الله يجعل من أضعفِ الأشياءِ أعظمَ آياته؛ فلا تحتقر سببًا يسيرًا جعله الله في يدك."}},{"n":19,"reflection":{"text":"«قال ألقها يا موسى» — قال الله: ألقِ عصاك يا موسى، أمرٌ بالطاعةِ ليرى الآية؛ ففي هذا أنّ امتثالَ أمرِ الله بابُ رؤيةِ عجائبِ صنعه، وأنّ الطاعةَ تسبق المعرفة؛ فبادر إلى امتثالِ أمرِ الله وإن لم تعلم الحكمة، فبالطاعةِ تنفتح لك أبوابُ الفضل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ إلى امتثالِ أمرِ الله قبل معرفةِ الحكمة."},"action":{"text":"بادر إلى امتثالِ أمرِ الله بمجرّدِ سماعه وإن لم تدرك حكمته، كما ألقى موسى عصاه بأمرِ ربّه؛ فالطاعةُ العاجلةُ بابُ الخيرِ ورؤيةِ لطفِ الله وفضله."}},{"n":20,"reflection":{"text":"«فألقاها فإذا هي حية تسعى» — فألقى موسى عصاه، فإذا هي ثعبانٌ عظيمٌ يتحرّك بسرعةٍ وخفّة؛ ففي هذا ظهورُ آيةِ الله بقلبِ الجمادِ حيوانًا، وأنّ قدرةَ الله تخرق العادات؛ فأيقن بقدرةِ الله التي تحيل الأشياءَ كيف تشاء، فما من مستحيلٍ على من يقول للشيءِ كن فيكون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بقدرةِ الله التي تخرق العادات."},"action":{"text":"أيقن بأنّ قدرةَ الله لا يحدّها معتاد، فهو يقلب العصا حيّةً والجمادَ حيوانًا؛ فلا تستبعد على الله شيئًا، وعلّق رجاءك بقدرته التي لا يعجزها شيء."}},{"n":21,"reflection":{"text":"«قال خذها ولا تخف سنعيدها سيرتها الأولى» — قال الله: خذ الحيّةَ ولا تخف منها، سنعيدها عصًا كما كانت؛ ففي هذا تثبيتُ الله لعبده وطمأنتُه عند الخوف، وأنّ من كان الله معه فلا يخاف؛ فإذا خفت فالتجئ إلى الله يثبّتك ويؤمّنك، فالأمنُ الحقيقيُّ في معيّةِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["خذها ولا تخف"],"heart_state":{"text":"الالتجاءُ إلى الله عند الخوفِ طلبًا للتثبيت."},"action":{"text":"إذا داخلك خوفٌ فالتجئ إلى الله واذكره يثبّت قلبك ويؤمّنك، فقد قال لموسى «ولا تخف»؛ فمن كان الله معه بالطاعةِ والتوكّلِ زال خوفه واطمأنّ قلبه."}},{"n":22,"reflection":{"text":"«واضمم يدك إلى جناحك تخرج بيضاء من غير سوء آية أخرى» — وأدخل يدك تحت عضدك ثم أخرجها تخرج بيضاءَ نيّرةً من غيرِ برصٍ ولا مرض، آيةً أخرى دالّةً على صدقك؛ ففي هذا تأييدُ الله لرسوله بآيتين متعاضدتين، وأنّ الله يقوّي رسله بالبراهين؛ فاعلم أنّ الله يؤيّد أولياءه ويقوّيهم بما يثبّت الحقّ، فاعتمد على تأييده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ الله يؤيّد أولياءه ويقوّيهم بالبراهين."},"action":{"text":"ثق بأنّ الله يؤيّد أهلَ الحقِّ ويقوّيهم بما يثبّت دعوتهم، كما أيّد موسى بآيتين؛ فامضِ في الحقِّ معتمدًا على تأييدِ الله، فمن نصره الله فلا غالبَ له."}},{"n":23,"reflection":{"text":"«لنريك من آياتنا الكبرى» — فعلنا ذلك لنُريك يا موسى من آياتنا العظيمةِ الدالّةِ على قدرتنا وصدقِ رسالتك؛ ففي هذا أنّ الله يري عباده من آياته ما يزيدهم يقينًا وثباتًا، وأنّ الآياتِ حجّةٌ ورحمة؛ فتأمّل آياتِ الله في الآفاقِ والأنفسِ لتزداد يقينًا، فكلُّ آيةٍ تدلّ على عظمةِ خالقها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ آياتِ الله لزيادةِ اليقينِ والثبات."},"action":{"text":"تأمّل آياتِ الله الكبرى في الكونِ وفي كتابه لتزداد يقينًا وثباتًا على الحقّ؛ فالله يُري عباده من آياته ما يقوّي إيمانهم، فاجعل تدبّرها زادًا لقلبك."}},{"n":24,"reflection":{"text":"«اذهب إلى فرعون إنه طغى» — اذهب يا موسى إلى فرعونَ فادعُه إلى الله، إنه تجاوز الحدَّ في الكفرِ والظلمِ والطغيان؛ ففي هذا أنّ الدعوةَ تبدأ بأهلِ الطغيانِ رحمةً بهم، وأنّ على الداعيةِ أن يصدع بالحقِّ أمام الطغاة؛ فادعُ إلى الله ولو أعتى الناس، ولا يمنعك طغيانُ أحدٍ من إبلاغه الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["إنه طغى"],"heart_state":{"text":"الصدعُ بالدعوةِ إلى الله ولو أمام الطغاة."},"action":{"text":"ابلغ الحقَّ وادعُ إليه ولو كان المدعوُّ طاغيًا متجبّرًا، فموسى أُرسِل إلى فرعونَ مع طغيانه؛ فلا يمنعك جاهُ أحدٍ أو بطشُه من إبلاغِ كلمةِ الحقّ برفقٍ وحكمة."}}]},{"title":"دعاءُ موسى الجامع","range":[25,35],"theme":"سؤالُ موسى ربَّه شرحَ الصدرِ وتيسيرَ الأمرِ وعونَ أخيه","verses":[{"n":25,"reflection":{"text":"«قال رب اشرح لي صدري» — قال موسى: ربِّ وسّع لي صدري واجعله منشرحًا للحقِّ محتملًا للأذى وثقلِ الرسالة؛ ففي هذا أنّ انشراحَ الصدرِ عونٌ على الطاعةِ والدعوة، وأنه يُطلَب من الله؛ فاسأل الله أن يشرح صدرك للحقِّ ولكلِّ ما يشقّ عليك، فبانشراحِ الصدرِ يهون الصعب.","source":"تفسير السعدي","grade":"ma'thur"},"names":["اشرح لي صدري"],"heart_state":{"text":"طلبُ انشراحِ الصدرِ للحقِّ ولحملِ المشاقّ."},"action":{"text":"اسأل الله أن يشرح صدرك للطاعةِ والدعوةِ واحتمالِ الأذى، فبانشراحِ الصدرِ يخفّ عنك ثقلُ التكاليفِ والمصائب؛ فابدأ مهامك الكبارَ بهذا الدعاء."}},{"n":26,"reflection":{"text":"«ويسر لي أمري» — وسهّل لي أمري الذي كلّفتني به فلا أعجز عنه؛ ففي هذا طلبُ التيسيرِ من الله في كلِّ أمر، وأنّ اليُسرَ بيدِه وحده؛ فاطلب من الله تيسيرَ أمورك كلِّها قبل الإقدامِ عليها، فما يُسِّر أمرٌ إلا بتيسيرِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يسر لي أمري"],"heart_state":{"text":"طلبُ التيسيرِ من الله في كلِّ أمر."},"action":{"text":"اطلب من الله تيسيرَ أمرك قبل كلِّ عملٍ تقدم عليه، وقل «ربِّ يسّر لي أمري»؛ فما تعسّر أمرٌ إلا بمنعِ الله، وما تيسّر إلا بتيسيره، فالجأ إليه في كلِّ شأن."}},{"n":27,"reflection":{"text":"«واحلل عقدة من لساني» — وأطلق عن لساني العقدةَ التي تمنع فصاحتي؛ ففي هذا طلبُ موسى القدرةَ على البيانِ لأداءِ الدعوة، وأنّ البيانَ نعمةٌ تُطلَب لأجلِ الحقّ؛ فاسأل الله أن يعينك على البيانِ بالحقِّ وإبلاغه، فحسنُ البيانِ عونٌ على الدعوة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ القدرةِ على البيانِ لإبلاغِ الحقّ."},"action":{"text":"اسأل الله أن يفتح لك في البيانِ والقدرةِ على إيصالِ الحقِّ للناس، فحاجةُ الداعيةِ إلى البيانِ عظيمة؛ واعمل على تحسينِ بيانك ليكون أنفعَ في تبليغِ دينِ الله."}},{"n":28,"reflection":{"text":"«يفقهوا قولي» — كي يفهموا كلامي فيبلغهم الحقُّ واضحًا؛ ففي هذا أنّ غايةَ البيانِ إفهامُ المخاطَبِ لا مجردَ الكلام، وأنّ الداعيَ يقصد التفهيمَ لا التكلّف؛ فاحرص في دعوتك ومخاطبتك على أن يفهم الناسُ مرادك، فالمقصودُ إيصالُ المعنى لا التشدّقُ باللفظ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قصدُ إفهامِ المخاطَبِ في الدعوةِ والبيان."},"action":{"text":"اجعل غايتك في مخاطبةِ الناسِ أن يفهموا مرادك، فتخيّر من الألفاظِ أوضحَها وأقربَها لأفهامهم؛ فالبيانُ وسيلةٌ للتفهيمِ لا للتفاصح، وإفهامُ الحقِّ مقصودُ الدعوة."}},{"n":29,"reflection":{"text":"«واجعل لي وزيرا من أهلي» — واجعل لي معينًا ومؤازرًا من أهلي يشدّ عضدي؛ ففي هذا مشروعيةُ طلبِ العونِ الصالحِ على أمرِ الدين، وأنّ الاستعانةَ بالأعوانِ من الحزم؛ فاطلب من الله عونًا صالحًا يعينك على الخير، واستعن بأهلِ الصلاحِ في أمورك العظام.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العونِ الصالحِ والاستعانةُ به على الخير."},"action":{"text":"اطلب من الله معينًا صالحًا يؤازرك على الحقِّ والدعوة، واستعن بأهلِ الثقةِ والصلاحِ في أمورك الكبار؛ فالتعاونُ على البرِّ سنّةُ الأنبياءِ وقوّةٌ في الحقّ."}},{"n":30,"reflection":{"text":"«هارون أخي» — عيّن موسى من طلب: هارونَ أخي، لِما يعلم من صلاحه وقوّته؛ ففي هذا أنّ اختيارَ المعينِ يكون على أساسِ الصلاحِ والكفاءةِ والقرابةِ الصالحة، وأنّ صلةَ الرحمِ تقوى بالتعاونِ على الحقّ؛ فاختر أعوانك على الخيرِ من أهلِ الصلاحِ والكفاءة، وصِل رحمك بالتعاونِ على البرّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اختيارُ المعينِ على أساسِ الصلاحِ والكفاءة."},"action":{"text":"اختر من تستعين بهم على أمرك من أهلِ الصلاحِ والكفاءةِ والأمانة، وقدّم القريبَ الصالحَ فتجمع بين العونِ وصلةِ الرحم؛ فحسنُ اختيارِ العونِ نصفُ النجاح."}},{"n":31,"reflection":{"text":"«اشدد به أزري» — قوِّ به ظهري وأعنّي به على تبليغِ رسالتك؛ ففي هذا أنّ العونَ الصالحَ يشدّ أزرَ صاحبِ الحقِّ ويقوّيه، وأنّ القوّةَ في الاجتماع؛ فاطلب من الله ومن الصالحين ما يشدّ أزرك على الطاعة، فالمؤمنُ للمؤمنِ كالبنيانِ يشدّ بعضه بعضًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ ما يشدّ الأزرَ على الحقِّ والطاعة."},"action":{"text":"اطلب من الله ومن إخوانك الصالحين ما يقوّي عزمك ويشدّ أزرك على الطاعةِ والدعوة؛ فالاجتماعُ على الحقِّ قوّة، والمؤمنون يشدّ بعضهم بعضًا كالبنيان."}},{"n":32,"reflection":{"text":"«وأشركه في أمري» — واجعله شريكًا لي في النبوّةِ وأمرِ الدعوة؛ ففي هذا إيثارُ موسى لأخيه بالخيرِ العظيمِ وطلبُه له، وأنّ الحريصَ على الخيرِ يحبّه لغيره؛ فأحبَّ لإخوانك ما تحبُّ لنفسك من الخير، وأشركهم في الفضلِ ولا تستأثر به دونهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محبّةُ الخيرِ للغيرِ وإشراكُهم في الفضل."},"action":{"text":"أحبَّ لإخوانك من الخيرِ ما تحبُّ لنفسك، وأشركهم في الفضلِ والأعمالِ الصالحةِ ولا تستأثر به؛ فموسى طلب لأخيه شرفَ النبوّةِ معه، فكن كريمًا محبًّا للخيرِ لغيرك."}},{"n":33,"reflection":{"text":"«كي نسبحك كثيرا» — طلبتُ ذلك كي نسبّحك تسبيحًا كثيرًا معًا؛ ففي هذا أنّ الغايةَ من طلبِ العونِ إعانتُه على عبادةِ الله لا على الدنيا، وأنّ التعاونَ يكون على الذكرِ والتسبيح؛ فاجعل غايةَ استعانتك بالأعوانِ عبادةَ الله وذكره، لا مجردَ مصالحِ الدنيا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"جعلُ غايةِ التعاونِ عبادةَ الله وتسبيحه."},"action":{"text":"اجعل غايتك من كلِّ عونٍ وصحبةٍ أن تعينك على عبادةِ الله وذكره وتسبيحه، لا على الدنيا وحدها؛ فخيرُ الأعوانِ من أعانك على طاعةِ الله وذكرِه كثيرًا."}},{"n":34,"reflection":{"text":"«ونذكرك كثيرا» — ونذكرك ذكرًا كثيرًا بالقلبِ واللسان؛ ففي هذا فضلُ الإكثارِ من ذكرِ الله، وأنه غايةٌ يُطلَب العونُ لأجلها؛ فأكثر من ذكرِ الله في كلِّ حال، فالذكرُ الكثيرُ من أحبِّ الأعمالِ إلى الله وأنفعِها للقلب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من ذكرِ الله بالقلبِ واللسان."},"action":{"text":"أكثر من ذكرِ الله في قيامك وقعودك وعلى كلِّ حال، فالذاكرون الله كثيرًا والذاكراتُ لهم مغفرةٌ وأجرٌ عظيم؛ فاجعل لسانك رطبًا بذكرِ الله لا يفتر."}},{"n":35,"reflection":{"text":"«إنك كنت بنا بصيرا» — إنك يا ربّنا كنت بنا بصيرًا عالمًا بأحوالنا وما يصلحنا، فأنت أعلمُ بحاجتنا؛ ففي هذا التوسّلُ إلى الله بعلمه بحالِ عبده، وحسنُ الظنِّ بأنه يدبّر له ما يصلحه؛ فتوسّل إلى الله بعلمه بحالك، وفوّض أمرك إليه فهو أبصرُ بما ينفعك منك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["كنت بنا بصيرا"],"heart_state":{"text":"التوسّلُ إلى الله بعلمه، وتفويضُ الأمرِ إليه."},"action":{"text":"توسّل إلى الله بأنه بصيرٌ بحالك عالمٌ بما يصلحك، وفوّض أمرك إليه فهو أعلمُ بمصلحتك منك؛ فمن أيقن أنّ الله بصيرٌ به اطمأنّ إلى تدبيره ورضي بقضائه."}}]},{"title":"إجابةُ الدعاءِ وتذكيرُ موسى بالمنّةِ السابقة","range":[36,41],"theme":"استجابةُ الله لموسى، وتذكيرُه بحفظِه له طفلًا واصطناعِه لنفسه","verses":[{"n":36,"reflection":{"text":"«قال قد أوتيت سؤلك يا موسى» — قال الله: قد أعطيتك ما سألت يا موسى، إجابةً عاجلةً لدعائه؛ ففي هذا سرعةُ إجابةِ الله لعبده الصادقِ في دعائه، وأنّ الله كريمٌ يعطي من سأله؛ فادعُ الله واثقًا بالإجابة، وألحَّ عليه بالدعاءِ فهو يحبّ الملحّين ويعطي السائلين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بإجابةِ الله والإلحاحُ عليه بالدعاء."},"action":{"text":"ادعُ الله واثقًا بأنه يجيب، وألحَّ عليه بحوائجك كلِّها صغيرِها وكبيرِها؛ فقد أجاب موسى في دعائه كلِّه دفعةً واحدة، والله أكرمُ من أن يردَّ سائلًا صادقًا."}},{"n":37,"reflection":{"text":"«ولقد مننا عليك مرة أخرى» — ولقد أنعمنا عليك يا موسى نعمةً سابقةً أخرى قبل هذه؛ ففي هذا تذكيرُ الله عبده بسوابقِ نعمه لتقويةِ رجائه، وأنّ من أنعم عليك سابقًا لن يخذلك؛ فتذكّر سوابقَ نعمِ الله عليك ليقوى رجاؤك، فمن رعاك بالأمسِ لا يضيّعك اليوم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ سوابقِ نعمِ الله لتقويةِ الرجاء."},"action":{"text":"تذكّر نعمَ الله السابقةَ عليك في مواطنِ ضعفك وشدّتك، ليقوى رجاؤك في عونه الحاضر؛ فمن حفظك ورعاك بالأمسِ هو ربّك اليومَ لا يضيّعك، فأحسن الظنَّ به."}},{"n":38,"reflection":{"text":"«إذ أوحينا إلى أمك ما يوحى» — حين ألهمنا أمَّك إلهامًا بما فيه نجاتك؛ ففي هذا أنّ الله يلهم عباده ما فيه الخير، وأنّ عنايته تسبق العبدَ من مهده؛ فاعلم أنّ الله يدبّر لك الخيرَ من حيث لا تدري، وأنّ عنايته أحاطت بك قبل أن تعقل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطمأنينةُ إلى عنايةِ الله السابقةِ وتدبيرِه الخفيّ."},"action":{"text":"اطمئن إلى أنّ عنايةَ الله أحاطت بك من قبلِ أن تعقل، وأنه يدبّر لك الخيرَ بأسبابٍ خفيّةٍ لا تشعر بها؛ فمن رعاك في مهدك بلطفه يرعاك في كبرك، فثق به."}},{"n":39,"reflection":{"text":"«أن اقذفيه في التابوت فاقذفيه في اليم فليلقه اليم بالساحل يأخذه عدو لي وعدو له وألقيت عليك محبة مني ولتصنع على عيني» — أن ضعيه في الصندوقِ فألقيه في النهر، فيلقيه النهرُ بالشاطئ فيأخذه فرعونُ عدوّي وعدوّه (فيربّيه)، وألقيتُ عليك محبّةً منّي فأحبّك كلُّ من رآك، ولتُربّى بمرأًى منّي وحفظي؛ ففي هذا عجيبُ تدبيرِ الله: يربّي عدوُّه عدوَّه، وأنّ من أحبّه الله حبّبه للخلق؛ فسلّم لتدبيرِ الله العجيب، واعلم أنّ محبّةَ الخلقِ لك من الله، فاطلبها منه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ألقيت عليك محبة مني","ولتصنع على عيني"],"heart_state":{"text":"التسليمُ لتدبيرِ الله العجيب، وطلبُ محبّته وحفظه."},"action":{"text":"سلّم لتدبيرِ الله الذي يحفظ عبده بأعجبِ الأسباب حتى في حجرِ عدوّه، واطلب منه أن يلقي عليك محبّةً في قلوبِ خلقه؛ فالقبولُ والمحبّةُ عطاءٌ منه، والحفظُ بعينه."}},{"n":40,"reflection":{"text":"«إذ تمشي أختك فتقول هل أدلكم على من يكفله فرجعناك إلى أمك كي تقر عينها ولا تحزن وقتلت نفسا فنجيناك من الغم وفتناك فتونا فلبثت سنين في أهل مدين ثم جئت على قدر يا موسى» — حين تمشي أختك تتبّع أثرك فتقول لآلِ فرعون: هل أدلّكم على من يرضعه ويكفله؟ فرددناك إلى أمّك لترضعك فتفرح ولا تحزن، وقتلتَ نفسًا (القبطيَّ خطأً) فنجّيناك من هَمّ القصاص، واختبرناك اختبارًا، فمكثت سنين في مدين، ثم جئت في الوقتِ الذي قدّرناه لرسالتك؛ ففي هذا تتبّعُ عنايةِ الله لموسى في كلِّ أطوارِ حياته، وأنّ لكلِّ أمرٍ قدَرًا موقوتًا؛ فتأمّل عنايةَ الله بك في كلِّ مرحلة، واعلم أنّ ما يجري لك بقدَرٍ وحكمةٍ وتوقيت.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ عنايةِ الله في أطوارِ العمر، والرضا بقدَرِه الموقوت."},"action":{"text":"تأمّل كيف رعاك الله في كلِّ مرحلةٍ من عمرك ونجّاك من شدائد، وسلّم بأنّ كلَّ ما جرى لك جرى بقدَرٍ وحكمةٍ وتوقيتٍ من الله؛ فما جئت ولا وصلت إلا «على قدر»."}},{"n":41,"reflection":{"text":"«واصطنعتك لنفسي» — واصطفيتك وربّيتك على عيني لأجعلك رسولًا مختصًّا بحملِ رسالتي؛ ففي هذا شرفُ اصطفاءِ الله لموسى وتربيتِه له لخدمةِ دينه، وأنّ أشرفَ ما يُصطنَع له العبدُ حملُ رسالةِ الله؛ فاطلب أن يصطنعك الله لطاعته، فأشرفُ الغاياتِ أن يجعلك الله من خاصّتِه وأهلِ خدمةِ دينه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["واصطنعتك لنفسي"],"heart_state":{"text":"طلبُ أن يصطنعك الله لطاعته وخدمةِ دينه."},"action":{"text":"اطلب من الله أن يصطنعك لطاعته ويجعلك من أهلِ خدمةِ دينه، فأشرفُ ما يُصرَف فيه العمرُ حملُ رسالةِ الله والدعوةُ إليه؛ فاجعل حياتك مصنوعةً لله لا لهواك."}}]},{"title":"الأمرُ بالذهابِ إلى فرعونَ بالقولِ اللين","range":[42,48],"theme":"إرسالُ موسى وهارونَ معًا، والأمرُ بالرفقِ في الدعوةِ ووعدُ المعيّة","verses":[{"n":42,"reflection":{"text":"«اذهب أنت وأخوك بآياتي ولا تنيا في ذكري» — اذهب أنت وأخوك هارونُ بمعجزاتي الدالّةِ على صدقكما، ولا تفترا ولا تضعفا في ذكري والدعوةِ إليّ؛ ففي هذا أنّ الدعوةَ تحتاج إلى دوامِ الذكرِ وعدمِ الفتور، وأنّ الذكرَ زادُ الداعية؛ فلا تفتر عن ذكرِ الله في مسيرك ودعوتك، فبالذكرِ تقوى على المهامِّ الشاقّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"دوامُ الذكرِ وعدمُ الفتورِ في الدعوة."},"action":{"text":"لا تفتر عن ذكرِ الله في كلِّ أحوالك ولا سيّما عند المهامِّ الشاقّةِ والدعوةِ إلى الله، فالذكرُ زادُ الداعيةِ وقوّتُه؛ فمن لزم الذكرَ ثبّته الله وأعانه على الصعاب."}},{"n":43,"reflection":{"text":"«اذهبا إلى فرعون إنه طغى» — اذهبا كلاكما إلى فرعونَ فادعُواه، إنه جاوز الحدَّ في الكفرِ والظلم؛ ففي هذا تكرارُ الأمرِ بالذهابِ لأهمّيّته، وأنّ أعتى الطغاةِ لا يُيأَس من دعوته؛ فلا تيأس من دعوةِ أحدٍ مهما طغى، فبابُ الهدايةِ مفتوحٌ حتى للطغاةِ ما داموا أحياء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ اليأسِ من دعوةِ أحدٍ مهما طغى."},"action":{"text":"لا تيأس من هدايةِ أحدٍ مهما بلغ في الطغيانِ والبعدِ عن الحقّ، فادعُه ما دام حيًّا؛ فموسى وهارونُ أُرسِلا إلى فرعونَ أطغى الخلق، والهدايةُ بيدِ الله وحده."}},{"n":44,"reflection":{"text":"«فقولا له قولا لينا لعله يتذكر أو يخشى» — فخاطبا فرعونَ بكلامٍ رفيقٍ ليّنٍ لا غلظةَ فيه، رجاءَ أن يتّعظ أو يخاف الله فيرجع؛ ففي هذا أنّ الرفقَ في الدعوةِ أدعى للقبول حتى مع الطغاة، وأنّ اللينَ لا ينافي الصدعَ بالحقّ؛ فالزم الرفقَ واللينَ في دعوتك ونصحك، فالقلوبُ تُفتَح باللينِ لا بالعنف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["قولا له قولا لينا"],"heart_state":{"text":"لزومُ الرفقِ واللينِ في الدعوةِ والنصح."},"action":{"text":"خاطب من تدعوه أو تنصحه بكلامٍ ليّنٍ رفيقٍ ولو كان مخطئًا معاندًا، فاللينُ أدعى لقبولِ الحقّ؛ فإذا كان هذا مع فرعون، فأحرى أن تلين لمن دونه من الناس."}},{"n":45,"reflection":{"text":"«قالا ربنا إننا نخاف أن يفرط علينا أو أن يطغى» — قال موسى وهارون: ربّنا إننا نخاف أن يعجل علينا بالعقوبةِ قبل تبليغِ الرسالة، أو أن يطغى فيزداد كفرًا وأذًى؛ ففي هذا أنّ الخوفَ الطبيعيَّ لا ينافي المضيَّ في الطاعة، وأنّ العبدَ يرفع خوفه إلى الله؛ فارفع مخاوفك إلى الله واستعن به، ولا يمنعك خوفٌ طبيعيٌّ من المضيِّ في أمرِ ربّك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"رفعُ المخاوفِ إلى الله والمضيُّ في الطاعةِ رغمها."},"action":{"text":"ارفع مخاوفك وهواجسك إلى الله واستعن به عليها، ولا تدع الخوفَ الطبيعيَّ يقعدك عن طاعةٍ أمرك الله بها؛ فالأنبياءُ خافوا ثم مضوا متوكّلين، فاقتدِ بهم."}},{"n":46,"reflection":{"text":"«قال لا تخافا إنني معكما أسمع وأرى» — قال الله: لا تخافا من فرعون، إنني معكما بحفظي ونصري وتأييدي، أسمع ما يجري بينكم وأرى، فلن أسلّمكما إليه؛ ففي هذا وعدُ الله لرسله بالمعيّةِ الخاصّةِ التي تورث الأمنَ والنصر، وأنّ من كان الله معه فلا يخاف؛ فاطمئن إلى معيّةِ الله إذا كنت على الحقّ، فمعيّتُه حرزٌ من كلِّ خوف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["إنني معكما أسمع وأرى"],"heart_state":{"text":"الطمأنينةُ إلى معيّةِ الله الخاصّةِ لأهلِ الحقّ."},"action":{"text":"اطمئن إلى أنّ الله معك بحفظه ونصره إذا كنت على الحقِّ قائمًا بأمره، يسمع حالك ويرى، فلن يسلّمك لعدوّك؛ فمن استحضر معيّةَ الله زال خوفه وقوي قلبه."}},{"n":47,"reflection":{"text":"«فأتياه فقولا إنا رسولا ربك فأرسل معنا بني إسرائيل ولا تعذبهم قد جئناك بآية من ربك والسلام على من اتبع الهدى» — فأتيا فرعونَ فقولا: إنا رسولا ربّك، فأطلق معنا بني إسرائيلَ ولا تستعبدهم وتعذّبهم، قد جئناك بحجّةٍ من ربّك على صدقنا، والسلامةُ من العذابِ لمن اتّبع هدى الله؛ ففي هذا وضوحُ الرسالةِ وبيانُ المطلوب، وأنّ السلامةَ مقرونةٌ باتّباعِ الهدى؛ فابلغ الحقَّ واضحًا، واعلم أنّ النجاةَ كلَّها في اتّباعِ هدى الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["والسلام على من اتبع الهدى"],"heart_state":{"text":"إبلاغُ الحقِّ واضحًا، والعلمُ بأنّ السلامةَ في اتّباعِ الهدى."},"action":{"text":"ابلغ الحقَّ واضحًا محدّدًا بلا لبس، واعلم أنّ السلامةَ من عذابِ الله كلَّها في اتّباعِ هداه؛ فاجعل همّك اتّباعَ الهدى، وبلّغه لغيرك، فالنجاةُ موقوفةٌ عليه."}},{"n":48,"reflection":{"text":"«إنا قد أوحي إلينا أن العذاب على من كذب وتولى» — إنا قد أُوحِي إلينا أنّ العذابَ واقعٌ على من كذّب بآياتِ الله وأعرض عن طاعته؛ ففي هذا أنّ الإنذارَ جزءٌ من الرسالة، وأنّ عاقبةَ التكذيبِ والإعراضِ العذاب؛ فاحذر التكذيبَ بالحقِّ والإعراضَ عنه، فهما سببُ العذاب، والزم التصديقَ والإقبال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التكذيبِ بالحقِّ والإعراضِ عنه."},"action":{"text":"احذر أن تكذّب بشيءٍ من الحقِّ أو تُعرِض عن طاعةِ الله، فالعذابُ على من كذّب وتولّى؛ فالزم تصديقَ الحقِّ والإقبالَ على العمل، فبهما تنجو من الوعيد."}}]},{"title":"محاجّةُ موسى لفرعونَ في الربوبية","range":[49,55],"theme":"سؤالُ فرعونَ عن الربّ، وجوابُ موسى بآياتِ الخلقِ والهداية","verses":[{"n":49,"reflection":{"text":"«قال فمن ربكما يا موسى» — قال فرعونُ متكبّرًا منكرًا: فمن ربّكما الذي أرسلكما يا موسى؟ ففي هذا إنكارُ فرعونَ للربِّ استكبارًا، وأنّ الجاحدَ يسأل سؤالَ المعاند؛ فتهيّأ لأسئلةِ المعاندين بالحجّةِ الواضحة، ولا يهزّك إنكارُ منكِرٍ للحقِّ البيّن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ أمام إنكارِ المعاندين والاستعدادُ بالحجّة."},"action":{"text":"استعدَّ لأسئلةِ المعاندين وإنكارهم بالعلمِ والحجّةِ الواضحة، ولا يزعزعك جحودُهم للحقّ؛ فالحقُّ ثابتٌ وإن أنكره الطغاة، فاثبت عليه وأجب بالبيّنة."}},{"n":50,"reflection":{"text":"«قال ربنا الذي أعطى كل شيء خلقه ثم هدى» — قال موسى: ربّنا هو الذي أعطى كلَّ مخلوقٍ خلقته اللائقةَ به وما يصلحه، ثم هداه إلى منافعه ومعاشه؛ ففي هذا حجّةٌ قاطعةٌ على الربوبيّةِ بكمالِ الخلقِ والهداية، وأنّ من دبّر الخلقَ هو الربُّ المستحقُّ للعبادة؛ فتأمّل إتقانَ خلقِ الله وهدايتَه لكلِّ مخلوق، فذلك دليلُ ربوبيّته ووحدانيّته.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أعطى كل شيء خلقه ثم هدى"],"heart_state":{"text":"تأمّلُ إتقانِ الخلقِ والهدايةِ دليلًا على الربوبية."},"action":{"text":"تأمّل كيف أعطى الله كلَّ مخلوقٍ خلقته الكاملةَ ثم هداه لمصالحه، من أصغرِ نملةٍ إلى أعظمِ خلق؛ فذلك برهانُ ربوبيّته، فاعبده وحده وأخلص له لتمامِ خلقه وهدايته."}},{"n":51,"reflection":{"text":"«قال فما بال القرون الأولى» — قال فرعونُ محاولًا التشكيكَ والإفحام: فما حالُ الأممِ الماضيةِ التي لم تؤمن بربّك؟ (يريد أنها هلكت ولم تُبعَث)؛ ففي هذا محاولةُ المبطلِ صرفَ الحوارِ عن الحقِّ بأسئلةٍ جانبية؛ فلا تنجرّ وراء تشكيكاتِ المبطلين وأسئلتِهم الجانبيّةِ عن الحقِّ الواضح، وردَّ علمَ ما لا تعلمه إلى الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الانجرارِ وراء تشكيكاتِ المبطلين الجانبية."},"action":{"text":"لا تنجرّ وراء أسئلةِ المبطلين الجانبيّةِ التي يريدون بها صرفك عن الحقّ، والزم صلبَ الموضوع؛ وما سُئلت عنه ممّا لا تعلمه فردَّ علمه إلى الله بلا تكلّف."}},{"n":52,"reflection":{"text":"«قال علمها عند ربي في كتاب لا يضل ربي ولا ينسى» — قال موسى: علمُ أحوالِ تلك القرونِ عند ربّي مكتوبٌ في اللوحِ المحفوظ، لا يخطئ ربّي في علمه ولا ينسى شيئًا؛ ففي هذا ردُّ علمِ الغيبِ إلى الله، وإثباتُ كمالِ علمه الذي لا يضلّ ولا ينسى؛ فردَّ ما غاب عنك إلى علمِ الله، واطمئن إلى أنّ ربّك أحصى كلَّ شيءٍ لا يضلّ عنه ولا ينساه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لا يضل ربي ولا ينسى"],"heart_state":{"text":"ردُّ علمِ الغيبِ إلى الله، والطمأنينةُ إلى إحصائه."},"action":{"text":"ردَّ علمَ ما غاب عنك إلى الله، واطمئن إلى أنّ ربّك أحصى كلَّ شيءٍ في كتابٍ لا يخطئ ولا ينسى؛ فمن أيقن بذلك راقب الله في عمله، وعلم أنّ كلَّ شيءٍ محفوظ."}},{"n":53,"reflection":{"text":"«الذي جعل لكم الأرض مهدا وسلك لكم فيها سبلا وأنزل من السماء ماء فأخرجنا به أزواجا من نبات شتى» — ربّي الذي جعل لكم الأرضَ فراشًا ممهّدًا، وجعل لكم فيها طرقًا تسلكونها، وأنزل من السماءِ مطرًا فأخرجنا به أصنافًا من النباتِ المختلفة؛ ففي هذا تعدادُ نعمِ الله وآياتِه في الأرضِ والماءِ والنبات، وأنها دلائلُ ربوبيّته؛ فتأمّل نعمَ الله في أرضك وطعامك، فكلُّها آياتٌ تدلّ على المُنعِمِ وتدعو لشكره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ نعمِ الله وآياتِه في الأرضِ والنبات."},"action":{"text":"تأمّل نعمَ الله في الأرضِ الممهّدةِ والسبلِ الميسّرةِ والماءِ المنزَّلِ والنباتِ المتنوّع، واشكرها؛ فكلُّ ما حولك من نعمٍ آيةٌ على ربوبيّةِ الله ودعوةٌ لعبادته وشكره."}},{"n":54,"reflection":{"text":"«كلوا وارعوا أنعامكم إن في ذلك لآيات لأولي النهى» — كلوا ممّا أخرجنا من النبات، وارعوا فيه أنعامكم، إنّ في ذلك لدلالاتٍ واضحةً على قدرةِ الله لأصحابِ العقولِ السليمة؛ ففي هذا امتنانُ الله بالرزقِ للناسِ وأنعامهم، وأنّ الآياتِ يدركها أهلُ العقول؛ فكن من أولي النُّهى الذين يرون في النعمِ آياتِ الله، فيشكرونه ويعبدونه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لآيات لأولي النهى"],"heart_state":{"text":"أن يكون العبدُ من أولي النُّهى الذين يعتبرون بالآيات."},"action":{"text":"كن من أصحابِ العقولِ السليمةِ الذين ينظرون في نعمِ الله وآياته فيعتبرون ويشكرون ويعبدون؛ فلا تأكل رزقَ الله غافلًا عن مُنعِمه، بل اجعل كلَّ نعمةٍ سببًا لذكرِه."}},{"n":55,"reflection":{"text":"«منها خلقناكم وفيها نعيدكم ومنها نخرجكم تارة أخرى» — من الأرضِ خلقناكم (إذ خُلِق آدمُ من ترابها)، وفيها نعيدكم بالدفنِ بعد الموت، ومنها نخرجكم مرةً أخرى للبعثِ يوم القيامة؛ ففي هذا إثباتُ البعثِ بأطوارِ الإنسانِ الثلاثة، وأنّ الأرضَ مبدؤه ومعادُه؛ فتذكّر أصلك ومعادك من الأرض، ليقلَّ كِبرُك وتستعدَّ لبعثك الذي هو حقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ الأصلِ والمعادِ لكسرِ الكِبرِ وإثباتِ البعث."},"action":{"text":"تذكّر أنك من الأرضِ خُلِقت وإليها تعود ومنها تُبعَث، ليكسر ذلك كِبرك ويثبّت يقينك بالبعث؛ فمن استحضر أنه ترابٌ عائدٌ إلى ترابٍ ثم مبعوثٌ للحساب هان عليه التواضعُ والعمل."}}]},{"title":"تكذيبُ فرعونَ والمواعدةُ ليومِ الزينة","range":[56,64],"theme":"إباءُ فرعونَ بعد الآيات، ومواعدةُ السحرةِ، وتحذيرُ موسى لهم","verses":[{"n":56,"reflection":{"text":"«ولقد أريناه آياتنا كلها فكذب وأبى» — ولقد أرينا فرعونَ آياتنا كلَّها الدالّةَ على صدقِ موسى، فكذّب بها وامتنع عن الإيمانِ عنادًا واستكبارًا؛ ففي هذا أنّ الآياتِ لا تنفع مع العنادِ والكِبر، وأنّ التكذيبَ بعد البيانِ محضُ استكبار؛ فاحذر أن يحجبك الكِبرُ عن قبولِ الحقِّ بعد وضوحه، فما نفع فرعونَ رؤيةُ الآياتِ مع إبائه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يحجب الكِبرُ عن قبولِ الحقِّ الواضح."},"action":{"text":"احذر أن يمنعك الكِبرُ أو العنادُ من قبولِ الحقِّ بعد ما تبيّن لك، فالآياتُ لا تنفع قلبًا أباها استكبارًا؛ فذلّل نفسك للحقِّ متى ظهر، ولا تكن كفرعونَ رأى وأبى."}},{"n":57,"reflection":{"text":"«قال أجئتنا لتخرجنا من أرضنا بسحرك يا موسى» — قال فرعونُ متّهمًا موسى: أجئت لتخرجنا من ملكنا وأرضنا بسحرك؟ ففي هذا أنّ الطغاةَ يقلبون الحقائقَ ويتّهمون الداعيَ بإرادةِ الدنيا حمايةً لسلطانهم؛ فلا يصدّنك اتّهامُ المبطلين لك بسوءِ المقصد، فديدنُهم قلبُ الحقائقِ خوفًا على مصالحهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ أمام اتّهامِ المبطلين وقلبِهم للحقائق."},"action":{"text":"لا يصدّنك عن الحقِّ أن يتّهمك المبطلون بسوءِ القصدِ أو طلبِ الدنيا، فتلك حيلةُ الطغاةِ لصرفِ الناسِ عنك؛ فأخلص نيّتك لله، وامضِ في الحقِّ غيرَ عابئٍ بتهمهم."}},{"n":58,"reflection":{"text":"«فلنأتينك بسحر مثله فاجعل بيننا وبينك موعدا لا نخلفه نحن ولا أنت مكانا سوى» — قال فرعون: فلنعارضنّك بسحرٍ مثلِ ما جئت به، فاجعل بيننا وبينك موعدًا لا نخلفه نحن ولا أنت في مكانٍ مستوٍ عدلٍ بيننا؛ ففي هذا أنّ المبطلَ يعارض الحقَّ بالباطلِ ظنًّا أنه مثله، وأنّ الحقَّ يقبل التحدّي واثقًا؛ فثق بأنّ باطلَ المبطلين لن يقوى على الحقّ، ولا تهب مواجهتهم إذا كنت على بيّنة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ الباطلَ لا يقوى على الحقِّ عند المواجهة."},"action":{"text":"ثق بأنّ الحقَّ الذي معك أقوى من كلِّ باطلٍ يعارضه، فلا تهب مواجهةَ المبطلين ومناظرتهم إذا كنت على علمٍ وبيّنة؛ فالباطلُ زاهقٌ مهما تزيّن، والحقُّ ثابتٌ منصور."}},{"n":59,"reflection":{"text":"«قال موعدكم يوم الزينة وأن يحشر الناس ضحى» — قال موسى: موعدكم يومُ عيدكم الذي تتزيّنون فيه، وأن يُجمَع الناسُ وقتَ الضحى في النهارِ ليروا الحقّ؛ ففي هذا حرصُ موسى على إظهارِ الحقِّ أمام الجمعِ في وضحِ النهار، وأنّ الواثقَ بالحقِّ لا يخفيه؛ فأظهر الحقَّ في العلنِ ولا تخفه، فالحقُّ يزداد ظهورًا كلّما كثر شهوده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إظهارُ الحقِّ في العلنِ ثقةً به لا إخفاؤه."},"action":{"text":"أظهر الحقَّ في وضحِ النهارِ أمام الناسِ ولا تخفه، فالواثقُ بحقّه يطلب له أكثرَ الشهود؛ فموسى اختار يومَ الزينةِ وحشرَ الناسِ ضحًى ليظهر الحقُّ للجميع."}},{"n":60,"reflection":{"text":"«فتولى فرعون فجمع كيده ثم أتى» — فانصرف فرعونُ فجمع سحرته وحيلَه وما يكيد به، ثم حضر في الموعد؛ ففي هذا أنّ أهلَ الباطلِ يستفرغون جهدهم في نصرِ باطلهم، فكيف بأهلِ الحقّ؟ فاجمع لحقّك أسبابه وأعدَّ له عدّته، فإذا كان المبطلُ يجمع كيده فأهلُ الحقِّ أولى بالأخذِ بالأسباب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأخذُ بالأسبابِ ونصرةُ الحقِّ بالإعدادِ له."},"action":{"text":"خذ لحقّك بالأسبابِ وأعدَّ له عدّته، فإنّ أهلَ الباطلِ يجمعون كيدهم لنصرِ باطلهم، فأهلُ الحقِّ أولى بالإعدادِ والاجتهاد؛ فلا تتّكل مع إهمالِ الأخذِ بالأسباب."}},{"n":61,"reflection":{"text":"«قال لهم موسى ويلكم لا تفتروا على الله كذبا فيسحتكم بعذاب وقد خاب من افترى» — قال موسى للسحرة ناصحًا: ويحكم لا تختلقوا على الله كذبًا بمعارضةِ آياته بالسحر، فيهلككم بعذابٍ يستأصلكم، وقد خسر كلُّ من افترى على الله؛ ففي هذا نصحُ موسى حتى لأعدائه، وتحذيرُه من الافتراءِ على الله؛ فانصح حتى لمن يعاديك، وحذّر من الافتراءِ على الله فإنه سببُ الخيبةِ والهلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"النصحُ حتى للمخالف، والتحذيرُ من الافتراءِ على الله."},"action":{"text":"انصح للناسِ حتى لمن يعاديك ابتغاءَ هدايتهم كما نصح موسى للسحرة، وحذّرهم من الافتراءِ على الله؛ فمن كذب على الله أو عارض دينه بالباطلِ خاب وهلك، فاحذر ذلك."}},{"n":62,"reflection":{"text":"«فتنازعوا أمرهم بينهم وأسروا النجوى» — فاختلف السحرةُ في أمرهم بينهم بعد سماعِ نصحِ موسى، وتشاوروا سرًّا؛ ففي هذا أنّ كلمةَ الحقِّ تُحدِث أثرًا في القلوبِ ولو عند الخصوم، وأنّ التنازعَ بدايةُ التصدّع؛ فلا تحقر أثرَ كلمةِ الحقّ، فقد تزلزل قلوبَ المعاندين وتفتح فيهم ثغرةً للهدى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ احتقارِ أثرِ كلمةِ الحقِّ في القلوب."},"action":{"text":"لا تحقر أثرَ كلمةِ الحقِّ ولو قيلت لمعاند، فقد تزلزل يقينَه وتبعث فيه التردّدَ الذي يقود إلى الهدى؛ فقل الحقَّ وأحسِن قوله، ودع أثره إلى الله فهو يقلّب القلوب."}},{"n":63,"reflection":{"text":"«قالوا إن هذان لساحران يريدان أن يخرجاكم من أرضكم بسحرهما ويذهبا بطريقتكم المثلى» — قال أشرافُ فرعون أو هو: إنّ موسى وهارونَ ساحران يريدان إخراجكم من أرضكم بسحرهما وإذهابَ دينكم وسنّتكم الفُضلى؛ ففي هذا تخويفُ الطغاةِ للعامّةِ على الدينِ والدنيا لصدّهم عن الحقّ، وأنّ الباطلَ يتلبّس بحمايةِ المصالح؛ فاحذر دعاياتِ المبطلين التي تلبس الباطلَ لباسَ حمايةِ الدينِ والوطن، وزِن الأمورَ بالحقِّ لا بالتهويل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من دعاياتِ المبطلين المُلبِسةِ للباطل."},"action":{"text":"احذر دعاياتِ أهلِ الباطلِ التي تخوّف الناسَ على دينهم أو دنياهم لصدّهم عن الحقّ، وزِن كلَّ دعوى بميزانِ الحقِّ لا بالتهويلِ والإثارة؛ فالباطلُ كثيرًا ما يتلبّس بحمايةِ المصالح."}},{"n":64,"reflection":{"text":"«فأجمعوا كيدكم ثم ائتوا صفا وقد أفلح اليوم من استعلى» — فاعزموا على كيدكم واجمعوه، ثم احضروا مصطفّين لإرهابِ الخصم، وقد فاز اليومَ من غلب وعلا؛ ففي هذا إظهارُ الباطلِ لقوّتِه واجتماعِه، وأنّ ظنَّهم الفلاحَ في العلوِّ الظاهر؛ فلا يغرّنك اجتماعُ أهلِ الباطلِ وقوّتُهم الظاهرة، فالفلاحُ الحقيقيُّ لأهلِ الحقِّ لا لمن علا بالباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ باجتماعِ أهلِ الباطلِ وقوّتِهم الظاهرة."},"action":{"text":"لا يهزّك اجتماعُ أهلِ الباطلِ وكثرتُهم وقوّتُهم الظاهرة، فالفلاحُ الحقيقيُّ لمن علا بالحقِّ لا بالغلبةِ والباطل؛ فالعبرةُ بالعاقبةِ لا بالمظهر، والحقُّ يعلو ولا يُعلى عليه."}}]},{"title":"المباراةُ وإيمانُ السحرة","range":[65,73],"theme":"إلقاءُ السحرة، وتثبيتُ الله لموسى، وسجودُ السحرةِ وثباتُهم على الإيمان","verses":[{"n":65,"reflection":{"text":"«قالوا يا موسى إما أن تلقي وإما أن نكون أول من ألقى» — قال السحرةُ: يا موسى إما أن تلقيَ عصاك أوّلًا وإما أن نلقيَ نحن أوّلًا؛ ففي هذا أدبُهم الظاهرُ في التخيير، وثقةُ موسى بالحقِّ حتى خيّروه؛ فالواثقُ بالحقِّ لا يبالي أَبدأ خصمُه أم بدأ هو، فالعبرةُ بالعاقبةِ لا بالبداية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بالحقِّ وعدمُ المبالاةِ بترتيبِ المواجهة."},"action":{"text":"إذا كنت على حقٍّ فلا تبالِ من بدأ ومن تأخّر في المواجهة، فالحقُّ منصورٌ في العاقبة؛ فثق بحقّك وامضِ بطمأنينة، فالنصرُ للحقِّ لا للأسبقِ في الكلام."}},{"n":66,"reflection":{"text":"«قال بل ألقوا فإذا حبالهم وعصيهم يخيل إليه من سحرهم أنها تسعى» — قال موسى: بل ألقوا أنتم، فألقوا حبالهم وعصيّهم، فإذا هي يُخيَّل إليه من سحرهم أنها حيّاتٌ تسعى وتتحرّك؛ ففي هذا أنّ السحرَ تخييلٌ لا حقيقةَ له، وأنّ الباطلَ يُزيَّن حتى يُظنَّ حقًّا؛ فلا تنخدع بزخرفِ الباطلِ وتزيينه، فكثيرٌ ممّا يُبهِر ظاهرُه تخييلٌ لا حقيقة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الانخداعِ بزخرفِ الباطلِ وتخييله."},"action":{"text":"لا تنخدع بما يُبهِرك من زخرفِ الباطلِ وتزيينه، فكثيرٌ منه تخييلٌ لا حقيقةَ تحته كسحرِ السحرة؛ فزِن الأمورَ بحقيقتها لا بمظهرها، واثبت على الحقِّ وإن بهر الباطلُ الأعين."}},{"n":67,"reflection":{"text":"«فأوجس في نفسه خيفة موسى» — فأحسّ موسى في نفسه خوفًا خفيًّا (خشيةَ أن يلتبس على الناسِ الأمر)؛ ففي هذا أنّ الخوفَ الطبيعيَّ يعرض للأنبياء، وأنه لا ينافي التوكّل؛ فلا تلم نفسك على خوفٍ طبيعيٍّ يعرض لك، بل اجعله بابًا للالتجاءِ إلى الله والاستعانةِ به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقبّلُ الخوفِ الطبيعيِّ وجعلُه بابًا للالتجاء."},"action":{"text":"لا تحرج من خوفٍ طبيعيٍّ يعرض لقلبك عند الشدائد، فقد عرض لموسى؛ بل اجعله دافعًا للالتجاءِ إلى الله والاستعانةِ به، فبالافتقارِ إليه يأتي التثبيتُ والأمن."}},{"n":68,"reflection":{"text":"«قلنا لا تخف إنك أنت الأعلى» — قلنا لموسى: لا تخف، إنك أنت الغالبُ الأعلى على هؤلاء بالحجّةِ والنصر؛ ففي هذا تثبيتُ الله لعبده وبشارتُه بالعلوِّ والنصر، وأنّ العاقبةَ لأهلِ الحقّ؛ فاطمئن إلى وعدِ الله بالعلوِّ لأهلِ الحقّ، فمن كان مع الله فهو الأعلى وإن كثر خصومه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إنك أنت الأعلى"],"heart_state":{"text":"الطمأنينةُ إلى وعدِ الله بالعلوِّ لأهلِ الحقّ."},"action":{"text":"اطمئن إلى أنّ العاقبةَ والعلوَّ لأهلِ الحقِّ وإن اشتدّ الباطلُ وكثر أهله، فمن كان مع الله فهو الأعلى؛ فاثبت على الحقِّ واثقًا بنصرِ الله ولا يستخفّنّك الخوف."}},{"n":69,"reflection":{"text":"«وألق ما في يمينك تلقف ما صنعوا إنما صنعوا كيد ساحر ولا يفلح الساحر حيث أتى» — وألقِ عصاك التي في يمينك تبتلع ما صنعوه، فإنما صنعوا حيلةَ ساحرٍ، ولا يفلح الساحرُ أينما كان؛ ففي هذا أنّ الحقَّ يبتلع الباطلَ ويمحقه، وأنّ الباطلَ لا فلاحَ له ولا بقاء؛ فأيقن بأنّ حقّك سيمحق باطلَ خصومك، فالباطلُ لا يفلح ولا يدوم مهما تعاظم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الحقَّ يمحق الباطلَ ولا يفلح المبطل."},"action":{"text":"أيقن بأنّ الحقَّ يبتلع الباطلَ ويمحقه كما لقفت عصا موسى سحرَ السحرة، وأنّ المبطلَ لا يفلح أبدًا؛ فاثبت على حقّك، ولا يغرّنك تعاظمُ الباطلِ فإنه إلى زوال."}},{"n":70,"reflection":{"text":"«فألقي السحرة سجدا قالوا آمنا برب هارون وموسى» — فخرّ السحرةُ ساجدين لله حين تبيّن لهم الحقّ، وقالوا: آمنّا بربِّ هارونَ وموسى؛ ففي هذا أنّ العالمَ بحقيقةِ الأمرِ أسرعُ إلى الحقِّ (فالسحرةُ عرفوا أنّ ما رأوه ليس سحرًا)، وأنّ القلبَ إذا رأى الحقَّ خضع؛ فإذا تبيّن لك الحقُّ فاخضع له فورًا كما خضع السحرةُ، ولا يمنعك كِبرٌ ولا هوًى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ إلى الخضوعِ للحقِّ متى تبيّن."},"action":{"text":"إذا تبيّن لك الحقُّ فاخضع له فورًا ولا تتردّد، كما سجد السحرةُ ساعةَ عرفوا الحقّ رغم ما ينتظرهم من بطشِ فرعون؛ فالمؤمنُ الصادقُ يتبع الحقَّ حيث ظهر مهما كلّفه."}},{"n":71,"reflection":{"text":"«قال آمنتم له قبل أن آذن لكم إنه لكبيركم الذي علمكم السحر فلأقطعن أيديكم وأرجلكم من خلاف ولأصلبنكم في جذوع النخل ولتعلمن أينا أشد عذابا وأبقى» — قال فرعونُ مهدّدًا: آمنتم بموسى قبل أن آذن لكم؟ إنه كبيركم الذي علّمكم السحر! فلأقطّعنّ أيديكم وأرجلكم من خلافٍ ولأصلبنّكم في جذوعِ النخل، ولتعلمنّ أيُّنا أشدُّ عذابًا وأبقى؛ ففي هذا بطشُ الطاغيةِ بمن آمن، وتهديدُه لصرفهم عن الحقّ؛ فاعلم أنّ أهلَ الحقِّ قد يُبتلَون ببطشِ الطغاة، فاثبت ولا يزلزلك التهديد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ رغمَ تهديدِ الطغاة."},"action":{"text":"اثبت على الحقِّ الذي عرفته ولو هدّدك الطغاةُ بأشدِّ العقوبات، فتهديدُهم لا يغيّر الحقّ، وعذابُهم منقطعٌ وعذابُ الله أشدُّ وأبقى؛ فقدّم رضا الله على سلامةِ الدنيا."}},{"n":72,"reflection":{"text":"«قالوا لن نؤثرك على ما جاءنا من البينات والذي فطرنا فاقض ما أنت قاض إنما تقضي هذه الحياة الدنيا» — قال السحرةُ لفرعون: لن نختارك ونطيعك على ما جاءنا من الحججِ الواضحةِ وعلى الذي خلقنا، فاصنع ما أنت صانع، إنما سلطانك في هذه الحياةِ الدنيا الزائلة؛ ففي هذا كمالُ ثباتِ المؤمنِ حين يذوق حلاوةَ الإيمان، وأنّ من عرف اللهَ هان عليه بطشُ الخلق؛ فإذا رسخ الإيمانُ في قلبك هان في عينك كلُّ تهديدٍ دنيويّ، فآثِر الله على كلِّ شيء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ الله على الدنيا، وهوانُ بطشِ الخلقِ عند المؤمن."},"action":{"text":"آثِر رضا الله على كلِّ سلطانٍ ومتاعٍ في الدنيا، واعلم أنّ بطشَ الخلقِ منقطعٌ لا يتجاوز الدنيا الفانية؛ فمن ذاق حلاوةَ الإيمانِ هان عليه كلُّ تهديد، كالسحرةِ الذين قالوا «فاقض ما أنت قاض»."}},{"n":73,"reflection":{"text":"«إنا آمنا بربنا ليغفر لنا خطايانا وما أكرهتنا عليه من السحر والله خير وأبقى» — قال السحرةُ: إنا آمنّا بربّنا رجاءَ أن يغفر لنا ذنوبنا وما أكرهتنا عليه من تعلّمِ السحرِ ومزاولته، والله خيرٌ منك ثوابًا وأبقى عقوبةً وجزاءً؛ ففي هذا رجاءُ التائبِ مغفرةَ الله، وموازنتُهم بين ثوابِ الله الباقي ومتاعِ فرعونَ الزائل؛ فوازِن بين ما عند الله الباقي وما عند الدنيا الفاني، واطلب المغفرةَ بالتوبةِ والإيمان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["والله خير وأبقى"],"heart_state":{"text":"رجاءُ المغفرةِ بالتوبة، وإيثارُ ما عند الله الباقي."},"action":{"text":"بادر بالتوبةِ والإيمانِ راجيًا مغفرةَ الله لِما سلف من ذنوبك، ووازِن دائمًا بين ما عند الله الباقي وما في الدنيا الفاني، فالله خيرٌ وأبقى؛ فلا تبع الباقيَ بالفاني، واطلب رضاه."}}]},{"title":"عاقبةُ الفريقين، ونجاةُ بني إسرائيلَ وغرقُ فرعون","range":[74,79],"theme":"جزاءُ المجرمِ والمؤمن، والإسراءُ ببني إسرائيلَ في البحرِ وإغراقُ فرعون","verses":[{"n":74,"reflection":{"text":"«إنه من يأت ربه مجرما فإن له جهنم لا يموت فيها ولا يحيى» — إنّ من يلقَ ربّه مجرمًا كافرًا فإنّ جزاءه جهنمُ، لا يموت فيها فيستريح ولا يحيا حياةً طيّبةً ينتفع بها؛ ففي هذا هولُ عذابِ المجرمِ الدائمِ الذي لا موتَ فيه ولا راحة؛ فاحذر أن تلقى الله مجرمًا، فعذابُ المجرمِ لا انقطاعَ له ولا راحةَ فيه، فبادر بالتوبةِ قبل اللقاء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من لقاءِ الله مجرمًا خشيةَ العذابِ الدائم."},"action":{"text":"احذر أن تلقى الله على إجرامٍ وكفرٍ ومعصيةٍ مصرًّا، فجزاءُ المجرمِ نارٌ لا موتَ فيها ولا حياة؛ فبادر بالتوبةِ والإصلاحِ قبل أن تلقى ربّك، فاللقاءُ آتٍ لا محالة."}},{"n":75,"reflection":{"text":"«ومن يأته مؤمنا قد عمل الصالحات فأولئك لهم الدرجات العلى» — ومن يلقَ ربّه مؤمنًا قد عمل الصالحاتِ فأولئك لهم المنازلُ الرفيعةُ في الجنة؛ ففي هذا أنّ الدرجاتِ العلى تُنال بالإيمانِ والعملِ الصالحِ معًا، وأنّ الجزاءَ على قدرِ العمل؛ فاجمع بين الإيمانِ والعملِ الصالح، واطلب الدرجاتِ العلى بالمنافسةِ في الطاعات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الدرجاتِ العلى بالإيمانِ والعملِ الصالح."},"action":{"text":"اجمع بين صدقِ الإيمانِ وصالحِ العمل، ونافس في الطاعاتِ لتبلغ الدرجاتِ العلى في الجنة؛ فالجزاءُ على قدرِ العمل، فلا ترضَ لنفسك بالدون، واطلب أعلى المنازلِ عند الله."}},{"n":76,"reflection":{"text":"«جنات عدن تجري من تحتها الأنهار خالدين فيها وذلك جزاء من تزكى» — تلك الدرجاتُ جناتُ إقامةٍ دائمةٍ تجري من تحتها الأنهار، ماكثين فيها أبدًا، وذلك جزاءُ من تطهّر من الشركِ والمعاصي بالإيمانِ والعملِ الصالح؛ ففي هذا أنّ التزكيةَ (تطهيرَ النفس) سببُ الفوزِ بجناتِ عدن، وأنّ الطهارةَ طريقُ النعيمِ المقيم؛ فاعمل على تزكيةِ نفسك من الشركِ والذنوبِ والأخلاقِ الرديئة، فبها تُنال جناتُ عدن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ على تزكيةِ النفسِ لنيلِ جناتِ عدن."},"action":{"text":"اعمل على تزكيةِ نفسك: طهّرها من الشركِ والمعاصي والأخلاقِ الذميمةِ بالإيمانِ والعملِ والتوبة؛ فجناتُ عدنٍ جزاءُ من تزكّى، فقد أفلح من زكّى نفسه، فاجعل التزكيةَ همّك."}},{"n":77,"reflection":{"text":"«ولقد أوحينا إلى موسى أن أسر بعبادي فاضرب لهم طريقا في البحر يبسا لا تخاف دركا ولا تخشى» — ولقد أوحينا إلى موسى أن سِر ليلًا بعبادي (بني إسرائيل)، فاضرب لهم بعصاك طريقًا يابسًا في البحر، لا تخاف أن يدركك فرعونُ ولا تخشى الغرق؛ ففي هذا نصرُ الله لأوليائه بخرقِ العادات، وأمرُه لهم بالأخذِ بالسببِ مع التوكّل؛ فخذ بالأسبابِ وامضِ في طاعةِ الله واثقًا بنصره، فمن توكّل عليه كفاه ولم يخذله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لا تخاف دركا ولا تخشى"],"heart_state":{"text":"الأخذُ بالأسبابِ مع التوكّلِ والثقةِ بنصرِ الله."},"action":{"text":"امضِ في طاعةِ الله آخذًا بالأسبابِ متوكّلًا عليه، ولا تخف مع صدقِ توكّلك إدراكَ عدوٍّ ولا هلاكًا؛ فمن كان الله ناصره شقّ له البحرَ وأنجاه، فالنصرُ لمن أطاعه وتوكّل عليه."}},{"n":78,"reflection":{"text":"«فأتبعهم فرعون بجنوده فغشيهم من اليم ما غشيهم» — فلحق فرعونُ ببني إسرائيلَ بجنوده في البحر، فغمرهم من الماءِ ما غمرهم فأغرقهم جميعًا؛ ففي هذا عاقبةُ الطاغيةِ الذي طارد أولياءَ الله، وأنّ الله يهلك الظالمين في ذاتِ ما يطلبون به الأذى؛ فاعتبر بعاقبةِ من عادى أولياءَ الله، فإنّ الله ينتقم للحقِّ ويهلك الظالمين حيث ظنّوا الغلبة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ من عادى أولياءَ الله وطاردهم."},"action":{"text":"اعتبر بعاقبةِ فرعونَ الذي طارد أولياءَ الله فأغرقه الله، واعلم أنّ الله ينتقم للحقِّ ولأوليائه ممّن ظلمهم؛ فلا تكن عونًا للظالمين على أهلِ الحقّ، فعاقبةُ الظلمِ وخيمة."}},{"n":79,"reflection":{"text":"«وأضل فرعون قومه وما هدى» — وأضلّ فرعونُ قومه عن سبيلِ الرشادِ بما زيّن لهم من الكفرِ والضلال، وما هداهم إلى خير؛ ففي هذا أنّ القادةَ المضلّين يحملون وزرَ إضلالِ أتباعهم، وأنّ من قلّد ضالًّا هلك معه؛ فاحذر أن تكون تابعًا لمُضِلٍّ أو قدوةَ سوءٍ لغيرك، والزم قادةَ الهدى لا قادةَ الغيّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من قادةِ الضلالِ ومن إضلالِ الغير."},"action":{"text":"احذر أن تتّبع قائدًا يضلّك عن الحقِّ كما أضلّ فرعونُ قومه، واحذر أن تكون أنت قدوةَ سوءٍ تضلّ غيرك؛ فالزم أهلَ الهدى واقتدِ بهم، وكن داعيًا للخيرِ لا للشرّ."}}]}],"coverage":{"covered":79,"total":135}};
